// Cooee Word — the answers, one for each day, each with a clue shown as the
// day's hint and the fact shown once the day's game is over. A thousand of
// them, so a word comes round again only after nearly three years. Every fact was checked against what its source
// publishes, and every line passes the banned terms scan like any other copy.
//
// This file is large, so only the game screen loads it, and only when it
// opens (src/ui/Word/WordScreen.tsx). Nothing else may import it.
//
// A day's answer is kept with that day's game on the phone, so this list may
// change without changing any day already played. Replace an entry in place
// or add to the end; never reorder.

export type WordSource = 'cfa' | 'bom' | 'ffmvic' | 'csiro' | 'redcross' | 'emv' | 'health' | 'agvic' | 'wildlife' | 'museumsvic';
